    "mapping_notes": [
      "Complete publisher-edition poem (PTS/BJTS), not a line-complete translation of every VRI stanza. Retain both authentic editions and all explicit differences; no missing words, numbers or line alignment are inferred.",
      "Explicit reviewed mapping: publisher chapter-3 poem 22 corresponds to canonical tha-ap24 by complete title, story and colophon evidence. Shared poem numbers or a numeric offset do not establish other mappings.",
      "Publisher55printed entries correspond to54numbered VRI stanzas after restoring opening52. Four source global-only entries882–885are substantive verse, not editorial apparatus; VRI69–70six-foot material is regrouped.",
      "Publisher local24/global892has constructed legs, whereas VRI78has chattamāropayiṃsu, raising an umbrella. Preserve the difference.",
      "Publisher local26/global894has a lamp shining by day, whereas VRI80padīpopi na pajjali has a lamp not burning/shining. Preserve the opposite formulation without silent correction.",
      "Publisher local30/global898has faith in Buddha’s words; VRI84main has viruddhā, opposition, and a visaddhā variant. No unrecorded identity of readings is inferred.",
      "Publisher local31/global899calls the speaker a speaker; VRI85bhatako is a hired worker, with varako retained as a variant. Preserve the occupational difference.",
      "Publisher original note9explains PTS/BJTS omission of garuḷas and height sequencing; the four global-only Kumbhaṇḍa stanzas and all source groups remain. Notes23–24retain unresolved lexicographic interpretations.",
      "Original malformed emphasis in local22/global890leaves an unmatched literal asterisk under the matched-emphasis-only presentation recipe. Preserve the residue and all words rather than editorially repairing the source."
    ],
