      "VRI summary list itself has Susūti and repeated Khomadāyī/group wording, omitting several names listed by the complete publisher ten-name summary. Preserve both edition lists; do not infer line alignment or silently repair VRI.",
      "The VRI summary’s count phrase is retained literally in the root and is not assigned a normalized numerical interpretation by this review.",
      "The publisher chapter-title colophon is the ninth line of the second summary paragraph; no blank paragraph is invented before it. The fourth-recitation marker follows as separate canonical apparatus."
