      "Thirteen original notes belong to the poem, with four finite paired Markdown c/ch displays in notes5,6,10,11. No external cross-reference or unreviewed poem becomes active through these notes.",
      "Publisher Opavuyha differs from VRI title/colophon Opavayha; the horse/Devala/replacement-gift narrative confirms identity independently of that spelling.",
      "Publisher notes4–7 explicitly choose BJTS readings. VRI36 khamanīyam and VRI37 devattaṃ atha mānusaṃ agree in parts, but VRI37 main cittaṃ differs from the plural horses formulation in the publisher and its recorded VRI variant cittā. Do not claim literal word alignment.",
